    if (own.isEmpty) continue;
    final cleaned = own.replaceFirst(RegExp(r'^\s+'), '');
    if (cleaned != own) {
      e
        ..nodes.clear()
        ..append(dom.Text(cleaned));
    }
  }
  return body.innerHtml;
}

